CREATE TYPE "VerificationStatus" AS ENUM ('CONFIRMED','JUDGMENT_CONFIRMED_REASON_UNVERIFIED','PAST_EXAM_ONLY','SOURCE_UNCERTAIN');
CREATE TYPE "MasteryStatus" AS ENUM ('NEW','LEARNING','REVIEW','MASTERED','RELEARNING');
CREATE TYPE "StudyMode" AS ENUM ('TODAY','SUBJECT','WRONG','RANDOM');
CREATE TABLE "Subject" ("id" UUID PRIMARY KEY,"slug" TEXT NOT NULL UNIQUE,"name" TEXT NOT NULL,"sortOrder" INTEGER NOT NULL);
CREATE TABLE "StudyItem" ("id" UUID PRIMARY KEY,"subjectId" UUID NOT NULL REFERENCES "Subject"("id"),"sourceItemKey" TEXT NOT NULL UNIQUE,"questionGroup" TEXT NOT NULL,"sourceType" TEXT NOT NULL,"itemType" TEXT NOT NULL,"statementText" TEXT NOT NULL,"correctJudgment" BOOLEAN NOT NULL,"judgmentSource" TEXT NOT NULL,"explanation" TEXT NOT NULL,"explanationType" TEXT NOT NULL,"sourceReference" TEXT NOT NULL,"verificationStatus" "VerificationStatus" NOT NULL,"reviewEligible" BOOLEAN NOT NULL,"judgmentAsOf" DATE,"historicalJudgment" BOOLEAN,"historicalContext" TEXT,"timeSensitive" BOOLEAN NOT NULL DEFAULT false,"caution" TEXT,"sourceDocument" TEXT NOT NULL,"sourceQuestionNumber" TEXT NOT NULL,"sourceItemNumber" INTEGER NOT NULL,"sourceHeading" TEXT NOT NULL,"sourceOrder" INTEGER NOT NULL,"metadata" JSONB NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "User" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"email" TEXT NOT NULL UNIQUE,"passwordHash" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "LoginSession" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"tokenHash" TEXT NOT NULL UNIQUE,"userId" UUID NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"expiresAt" TIMESTAMP(3) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "StudySession" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"userId" UUID NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"mode" "StudyMode" NOT NULL,"subjectId" UUID REFERENCES "Subject"("id"),"requestedCount" INTEGER NOT NULL,"localDate" TEXT,"startedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"endedAt" TIMESTAMP(3));
CREATE TABLE "StudySessionItem" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"sessionId" UUID NOT NULL REFERENCES "StudySession"("id") ON DELETE CASCADE,"studyItemId" UUID NOT NULL REFERENCES "StudyItem"("id"),"position" INTEGER NOT NULL);
CREATE TABLE "AnswerAttempt" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"userId" UUID NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"studyItemId" UUID NOT NULL REFERENCES "StudyItem"("id"),"sessionId" UUID REFERENCES "StudySession"("id"),"requestId" UUID NOT NULL,"selectedJudgment" BOOLEAN NOT NULL,"isCorrect" BOOLEAN NOT NULL,"wasUnsure" BOOLEAN NOT NULL DEFAULT false,"answeredAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"responseMs" INTEGER);
CREATE TABLE "StudyItemProgress" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"userId" UUID NOT NULL REFERENCES "User"("id") ON DELETE CASCADE,"studyItemId" UUID NOT NULL REFERENCES "StudyItem"("id"),"attemptsCount" INTEGER NOT NULL DEFAULT 0,"correctCount" INTEGER NOT NULL DEFAULT 0,"incorrectCount" INTEGER NOT NULL DEFAULT 0,"consecutiveCorrect" INTEGER NOT NULL DEFAULT 0,"lastAnsweredAt" TIMESTAMP(3),"lastResult" BOOLEAN,"lastWasUnsure" BOOLEAN,"masteryStatus" "MasteryStatus" NOT NULL DEFAULT 'NEW',"nextReviewAt" TIMESTAMP(3),"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "ReviewSettings" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"userId" UUID NOT NULL UNIQUE REFERENCES "User"("id") ON DELETE CASCADE,"newItemsPerDay" INTEGER NOT NULL DEFAULT 10,"dailyReviewLimit" INTEGER NOT NULL DEFAULT 50,"includeSourceUncertain" BOOLEAN NOT NULL DEFAULT false,"timezone" TEXT NOT NULL DEFAULT 'Asia/Tokyo',"examDate" DATE,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE UNIQUE INDEX "StudySession_userId_mode_localDate_key" ON "StudySession"("userId","mode","localDate");
CREATE UNIQUE INDEX "StudySessionItem_sessionId_studyItemId_key" ON "StudySessionItem"("sessionId","studyItemId");
CREATE UNIQUE INDEX "StudySessionItem_sessionId_position_key" ON "StudySessionItem"("sessionId","position");
CREATE UNIQUE INDEX "AnswerAttempt_userId_requestId_key" ON "AnswerAttempt"("userId","requestId");
CREATE UNIQUE INDEX "AnswerAttempt_sessionId_studyItemId_key" ON "AnswerAttempt"("sessionId","studyItemId");
CREATE UNIQUE INDEX "StudyItemProgress_userId_studyItemId_key" ON "StudyItemProgress"("userId","studyItemId");
CREATE INDEX "StudyItem_subjectId_active_reviewEligible_idx" ON "StudyItem"("subjectId","active","reviewEligible");
CREATE INDEX "StudyItem_verificationStatus_idx" ON "StudyItem"("verificationStatus");
CREATE INDEX "LoginSession_userId_expiresAt_idx" ON "LoginSession"("userId","expiresAt");
CREATE INDEX "StudySession_userId_startedAt_idx" ON "StudySession"("userId","startedAt");
CREATE INDEX "AnswerAttempt_userId_studyItemId_answeredAt_idx" ON "AnswerAttempt"("userId","studyItemId","answeredAt");
CREATE INDEX "StudyItemProgress_userId_nextReviewAt_idx" ON "StudyItemProgress"("userId","nextReviewAt");
CREATE INDEX "StudyItemProgress_userId_masteryStatus_idx" ON "StudyItemProgress"("userId","masteryStatus");
ALTER TABLE "StudyItem" ADD CONSTRAINT "source_uncertain_not_eligible" CHECK ("verificationStatus" <> 'SOURCE_UNCERTAIN' OR "reviewEligible" = false);
ALTER TABLE "StudyItem" ADD CONSTRAINT "historical_context_required" CHECK ("historicalJudgment" IS NULL OR "historicalContext" IS NOT NULL);
